mapper.insert:
insert into CHB_PRODUCTS_ASSET_COMPARE ( REGIST_SEQNO, STATUS_BATCH, ACCOUNT, ASSET_ID, HOLD_QTY_AMOUNT, HOLD_SHARES, BANK_MARK, DATE_STATUS, GROUP_ID, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select A.* from (
select #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.statusBatch,jdbcType=VARCHAR} AS STATUS_BATCH, #{item.account,jdbcType=VARCHAR} AS ACCOUNT, #{item.assetId,jdbcType=VARCHAR} AS ASSET_ID, #{item.holdQtyAmount,jdbcType=DECIMAL} AS HOLD_QTY_AMOUNT, #{item.holdShares,jdbcType=DECIMAL} AS HOLD_SHARES, #{item.bankMark,jdbcType=VARCHAR} AS BANK_MARK, #{item.dateStatus,jdbcType=DATE} AS DATE_STATUS, #{item.groupId,jdbcType=VARCHAR} AS GROUP_ID, #{item.status,jdbcType=VARCHAR} AS STATUS, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME from dual
) A
